        content: `英語を勉強してるのに、いざ喋ろうとすると日本語で考えてしまう。

あるある。全員そう。

で、頭の中に浮かんだ日本語を英語に直そうとする。

**ここで詰まる。**

"で、結局" を英語にしてみてほしい。

"So, in the end"? 意味は合ってる。でもネイティブはそう言わない。

---

## 翻訳が間違いの原因

"で、結局" には "お前の話長いから要約しろ" という圧が入ってる。英語の "so, in the end" にその圧はない。

ネイティブが同じ場面で使うのは "so basically"。

so basically には "俺が今から3秒でまとめるから黙って聞け" のニュアンスがある。これが近い。

"殺意が湧いた" → "I felt murderous intent"? 映画の字幕か。

実際のネイティブは "I almost lost it" と言う。殺意じゃなくて、理性が飛びかけた。

"もともこもない" → "there is no origin or child"? 意味不明。

ネイティブは "that defeats the whole purpose"。目的を殺すという発想。

**同じ感情なのに、たとえが全部違う。**

翻訳しようとしてるからダメなんだ。

"で、結局" → "so, in the end" は翻訳。正確。でもネイティブは言わない。

"で、結局" → "so basically" は変換。少しズレてる。でもネイティブはこう言う。

**正確さと自然さはトレードオフ。教科書は正確さを教える。会話で必要なのは自然さ。**

---

## この方法で310個の口癖を英語にした

自分が日常で使ってる日本語を全部書き出した。310個。

"で、結局" "ぶっちゃけ" "殺意が湧いた" "もともこもない" "知らんけど"

全部、毎日使ってる。無意識に。息をするように。

310個全部やって見えたパターンが3つある。

### パターン1: 日本語は感情を名詞にする。英語は動作にする。

- 殺意が湧いた → I almost lost it（理性を失いかけた）
- 安心した → that's a relief（安堵が来た、じゃなくて荷が降りた）
- 違和感がある → something feels off（何かがズレてる）

### パターン2: 日本語は比喩が具体的。英語は比喩が抽象的。

- もともこもない → defeats the purpose（元と子 vs 目的を殺す）
- 猫をかぶる → put on a front（猫 vs 正面=facade）
- 腹が立つ → pissed off（腹 vs ......まあ、英語も具体的だった）

### パターン3: 日本語は主語を省略する。英語は主語が必須。

"ぶっちゃけ" -- 誰がぶっちゃけるのか不明。空気がぶっちゃける。

"not gonna lie" -- I'm not gonna lie。必ずIが入る。

日本語は場の空気が主語になれる。英語は必ず人間が主語。

---

## なぜ "翻訳" では英語が出てこないのか

正確に翻訳した英語は、文法的に正しくて、意味も合ってて、そしてネイティブが絶対に言わない文になる。

310個を知ってるのと使えるのは別の能力。辞書を暗記した人間が翻訳家になれないのと同じ。

**でも知らないものは使えない。** 知ってて使えないのと、知らなくて使えないのは違う。

英語を学ぼうとして、自分の日本語を初めて見た。

"で、結局" を1日何回使ってるか、数えたことがなかった。"ぶっちゃけ" がどんな場面で出てくるか、考えたことがなかった。

**英語が難しいんじゃなかった。自分の日本語を意識したことがなかった。**

---

## よくある疑問

**Google翻訳でよくない?**

Google翻訳は翻訳する。俺のシステムは変換する。

"で、結局" をGoogle翻訳に入れると "in the end" が出る。正確。でもネイティブは言わない。

"so basically" はGoogle翻訳では出ない。これが翻訳と変換の差。

**310個も覚えられない**

覚えなくていい。カレンダー形式。1日10個。毎月同じ31日分が繰り返される。

1日目に出会う。30日後にまた出会う。60日後にもう一度。いつの間にか口から出る。......理論上は。

**自分の口癖なんて意識したことない**

それが普通。310個書き出して初めて見えた。

英語の壁は英語力じゃない。自分の日本語を知らないことが壁。

---

## この310個、アプリに入れた

カレンダー形式。1日10個。毎月繰り返す。

全部に解説がついてる。なぜその英語なのか。日本語と何が違うのか。

解説は毎日直してる。昨日の自分が書いた解説を読んで、ゴミだと思う日がある。

まだ作ってる。


---

## とにおのバイブコーディング塾 #01 -- バイブコーディングって何

ちなみにこのアプリ、プログラミングなしで作った。

バイブコーディングという方法を使った。2025年に生まれた言葉。

意味はシンプル。

**AIに日本語で "こういうの作って" と言うだけで、アプリが作れる。**

コードは書かない。プログラミングの知識もいらない。必要なのは "こういうのが欲しい" という気持ちだけ。

---

**始め方。3ステップ。**

1. AIツールを開く -- Claude Code、Cursor、Replit。どれも無料で始められる
2. 作りたいものを日本語で説明する
3. AIが作る。気に入らなければ "ここ違う" と言う。直してくれる

これだけ。本当にこれだけ。

---

**実際にやったこと。**

"カレンダー形式で、1日10個の口癖を表示して、タップしたら英語が出る画面を作って"

と言った。3分後に画面が出てきた。

色がおかしかった。"ここ金色にして" と言った。直った。

"カテゴリで絞り込めるようにして" と言った。追加された。

会話してるだけ。友達に頼んでる感覚。

310個の口癖を英語にするのに半年かかった。それを表示するアプリを作るのは3日だった。

---

次回、AIへの注文の出し方を教える。`
