        content: `英単語、3日で忘れる。

apple。覚えた。beautiful。覚えた。circumstance。3日で消えた。

単語帳を何周もしてる。覚えて忘れて覚えて忘れる。無限ループ。

**やり方が間違ってる。**

---

## なぜ単語帳では覚えられないのか

単語帳の問題は、単語がバラバラなこと。

appleとbeautifulとcircumstanceの間に何の関係もない。脈絡ゼロ。脳が "これいつ使うんだ" と判断して、捨てる。

昨日の夕飯は覚えてないのに、10年前の文化祭の事件は覚えてる。

**人間はストーリーで記憶する。バラバラの事実は捨てる。**

逆に言えば、単語をストーリーにすれば忘れない。

---

## 50語を1つの物語にする方法

50個の単語を1つの物語にした。

例。College Partyシナリオ。舞台はTylerのアパート。土曜の夜。ルームメイトのBrandonが "ちょっと人呼ぶわ" と言って30人呼んだ。

10人のキャラがいる。

- Tyler -- ホスト。内向型。Alyssaのことで頭がいっぱい
- Brandon -- ルームメイト。パーティーアニマル。何も心配してない
- Rosa -- 冷静ツッコミ担当。水とAdvilを持参してきた
- Alyssa -- Tylerの好きな子。来るか来ないかわからない
- Jake -- DJ志望。AUXケーブルの支配権を巡ってBrandonと戦争中

50個の単語は、この物語の中に埋まってる。

普通の単語帳。

> bivouac -- 野営する

覚えられるか。覚えられない。いつ使うんだこれ。

同じ単語を物語に入れる。

Brandonが酔っ払って言う。"Dude, I'm bivouacking on this couch tonight. My room is a disaster zone."

Brandonの声で bivouac が聞こえる。ソファで野営する酔っ払い。この画が浮かぶ。

**単語がキャラの声で聞こえると、忘れない。**

---

## なぜサブプロットがあると単語が残るのか

50語 = 50文。50文はバラバラの文じゃない。物語になってる。

サブプロットが3本走ってる。

1. **Tyler → Alyssa** -- Alyssaは来るのか。Tylerは何回シャツを着替えるのか（3回着替えた）
2. **Brandon vs Jake** -- AUXケーブル戦争。誰がパーティーの音楽を仕切るか
3. **Professor Hayes** -- 隣の部屋から苦情。最初はメモ。次にドアノック。最後に......

50語の単語を覚えようとしてるのに、気づいたらAlyssaが来るか気になってる。

**それでいい。気になってる時点で物語に入ってる。物語に入ってる時点で単語は残る。**

---

## 年齢で英語は全部変わる

全部で15,000語。50語ずつ。年齢もバラバラにしてある。

- ベッドの下のモンスター（4歳、男）
- 親なしで初めての映画館（12歳、グループ）
- 大学パーティー（20歳、男）
- MLBポッドキャスト（大人、2人）
- 定年退職の最終日（62歳、男）

4歳のTimmyは "Mommy, the floor is lava!" と言う。

62歳のFrankは "Forty years. Can you believe it? Forty damn years." と言う。

**同じ英語でも、誰が喋るかで全部変わる。** 教科書はこの差を教えない。

---

## よくある疑問

**ストーリーで覚えるって、読書と同じじゃない?**

読書は読む。これは聴く。キャラの声で。

読んで覚えた単語は目で認識できる。聴いて覚えた単語は耳で認識できる。会話に必要なのは後者。

**15,000語って多すぎない?**

50語ずつ。1シナリオ5日。つまり300シナリオで約4年分。

1日10分聴くだけ。覚えようとしなくていい。物語が勝手に記憶してくれる。......理論上は。

**キャラ設定とか、本当に意味ある?**

ある。キャラが立ってると、文が声になる。

"Brandon thinks he's the life of the party" はRosaが言うから面白い。教科書のナレーターが言っても何も残らない。

---

## このキャラたち、アプリの中で喋ってる

声つきで。毎日。10人のパーティー組も、4歳のTimmyも、野球ファン2人も。

俺はまだ聞いてるだけ。でもキャラの名前は全部覚えた。

単語は......まだ半分。


---

## とにおのバイブコーディング塾 #02 -- AIへの注文の出し方

前回: バイブコーディング = AIに日本語で言うだけでアプリが作れる。

今回のコツ。**制約を入れろ。**

50語の物語を10人のキャラ付きで作れとAIに言った。最初に返ってきたのは小説だった。

x "面白い物語を書いて"

o "50語使って、キャラ10人、サブプロット3本、1日分の会話を書いて"

自由すぎる注文だとAIは暴走する。条件が多いほど結果がよくなる。

ラーメン屋で "なんかうまいの" と注文する人はいない。味噌、太麺、ネギ多め。具体的に言うほど欲しいものが出てくる。

---

次回、AIに見本を見せる技術を教える。`
