        title: 'リスニング教材はもういらない -- 4歳児の英語が一番聞き取りやすい理由',
        subtitle: '年齢で英語はこんなに変わる。なのに教材は全部同じ大人の英語',
        tags: ['英語', 'リスニング', '年齢', '会話'],
        published: true,
        noteUrl: 'https://note.com/tonio_english/n/n43fe0382e5dd',
        content: `リスニング教材を何時間聞いても、ネイティブとの会話は聞き取れない。

なぜか。

**教材の英語と本番の英語が別物だから。**

教材は全員同じ。きれいな発音。適切な速度。完璧な文法。面白くない。

実際のネイティブ? 年齢で英語が全然違う。教材はこの差を無視してる。

---

## 4歳と20歳の英語を比べてみる

4歳のTimmy。ベッドの下にモンスターがいると確信してる。

> "Mommy... I heard a noise. Under my bed. It went like... grrrr."

文が短い。5語以内。接続詞がない。grrrr が怖いの代わりに入ってる。怖いという単語を知らないから、音で伝える。

20歳のTyler。パーティーの準備中。

> "I'm lowkey freakin' out. Did Alyssa say she's comin'?"

lowkey。freakin'。comin'。

**同じ英語に見えない。**

Timmyの英語は教科書に近い。Tylerの英語は教科書から一番遠い。

---

## 聞き取りやすさには順番がある

4つの年齢別シナリオを作って、聞き取りやすさを並べた。

1. **4歳（Timmy）** -- 文が短い。語彙が少ない。予測できる
2. **12歳（Jayden）** -- スラングは増えるが文は短い
3. **大人（Marcus）** -- 文が長いがリズムが安定
4. **20歳（Tyler）** -- スラングが多い。省略が多い。予測不能

**一番わかりにくいのは20歳。**

直感に反する。20歳は若いから簡単だろうと思う。逆。20歳の英語はスラングの密度が最も高い。新しい表現をどんどん作る。辞書に載ってない。

4歳が一番わかりやすいのは、使える単語が少ないから。制約が明確さを生む。

---

## なぜリスニング教材では上達しないのか

英語学習の教材は、全員同じ大人の英語で統一されてる。

でも実際の世界には4歳も12歳も20歳も62歳もいる。全員英語が違う。

4歳のTimmyと話すのに、ビジネス英語は必要ない。20歳のTylerと話すのに、教科書英語は通じない。

**必要なのは、相手に合わせて聞き方を変える能力。**

この能力は、全年齢の英語を聞かないと育たない。

教材で何百時間リスニングしても、全部同じ大人の英語。守備範囲が広がらない。

---

## よくある疑問

**4歳の英語を聴いて意味あるの?**

ある。4歳の英語は語彙が少ないから、文の構造がむき出し。英語の骨格が見える。

しかもリスニングの成功体験が積める。"全部わかった" という感覚は、次のレベルへのエネルギーになる。

**20歳のスラングなんて覚えなくていいでしょ?**

覚えなくていい。でも聞き取れないと会話についていけない。

相手が lowkey、no cap、freakin' を使ってきたとき、意味はわからなくても "あ、スラングだな" と判断できるだけで全然違う。

**結局どの年齢から聴けばいい?**

4歳から。マジで。

---

## この年齢別シナリオ、全部アプリに入れた

4歳のTimmyから大人のMarcusまで。5日間 x 4シリーズ。声も変えてある。

聴き比べるだけで、年齢で英語がこんなに変わるのかと思う。

ちなみに俺のリスニング力は4歳レベルに最適化されてる。4歳児とならスムーズに会話できる。

......使う場面がない。


---

## とにおのバイブコーディング塾 #03 -- 見本を見せろ

前回: AIへの注文は具体的に。制約が多いほど結果がよくなる。

今回のコツ。**見本を先に見せろ。**

4歳と20歳の英語を書き分けさせた。最初は全部同じ大人の英語で返ってきた。

x "4歳の英語で会話書いて"

o "4歳の英語はこう。'Mommy, the floor is lava!' 'I heard a noise. Under my bed.' この特徴を維持して10行書いて"

見本なしだとAIは平均的な文を書く。見本を3つ見せると特徴を掴んで増幅してくれる。

自分が欲しいものの "完成品に一番近いもの" を先に見せる。スクショでも、他のサイトでも、手書きでもいい。

---

次回もお楽しみに。`
