        title: '八村塁の英語は上手くない。ただ止まらないだけ -- それが最強だった',
        subtitle: '中学の英語2の男がNBAで通訳なし7年目。その方法を全部調べた',
        tags: ['英語', 'NBA', '八村塁', 'スピーキング', '性格'],
