        content: `よくある英語の豆知識。

英語ネイティブの語彙は2万語。日本語ネイティブは4〜5万語。

倍以上ある。日本語のほうが多い。つまり英語のほうが覚える量少ない。

やった。勝った。日本語のほうが難しい。俺たちはすでにハードモードをクリアしてる。英語なんて楽勝......

**......と思った人、ここから先読まないほうがいいかもしれない。**

---

## その2万、数え方がおかしい

英語の語彙研究で使われる単位がある。word family。

drive。これが1 word family。

drives, drove, driven, driving, driver, drivers。

**全部まとめて1。**

7語で1カウント。

家族割にもほどがある。ソフトバンクでもここまでまとめない。

これで2万。

2016年にBrysbaertっていう研究者がちゃんと数え直した。アメリカ人の20歳が知ってる単語数。家族割じゃなくて1語ずつ数えた。

**42,000語。**

2万じゃなかった。倍以上いた。

日本語ネイティブの語彙数。大卒で45,000〜50,000語。

英語ネイティブ。42,000語。

**ほぼ同じ。**

さっきの安心感、返品させてもらう。

---

## 100語で英語の半分が読める。残り半分に4万語いる

語彙にはピラミッドがある。1930年代にZipfっていうハーバードの言語学者が見つけた法則。

**一番使われる単語は、2番目の2倍使われる。2番目は3番目の2倍。以下同文。**

英語で一番使われる単語。the。全テキストの約7%を占領してる。

the, of, and, to, a, in, is, it, for, was。

この10語で全テキストの25%。たった10語で4分の1。

**上位100語で約50%。**

上位1,000語で80%。

上位2,000語で87%。

ここまではボーナスステージ。覚えれば覚えるほど見返りがある。ソシャゲの序盤。ログインするだけで石がもらえる時期。

問題はここから。

87%から98%に到達するのに、さらに6,000語が必要。**たった11%のために。**

なんで98%が大事かっていうと、Nationっていう研究者が証明した。98%カバーがないと本を楽しく読めない。100語に2語わからないだけでストレスになる。

つまり語彙学習のコスパは指数関数的に悪化する。

序盤: 1,000語覚えたら80%読める。ありがとう。

中盤: 5,000語覚えたら93.5%読める。......まあ......

終盤: 8,000語覚えたら98%読める。......3,000語追加して4.5%......?

**同じゲームだとは思えない。運営が途中で変わったとしか思えない。**

---

## 頭の中は高級マンション。でも半分空室

もっと嫌な話をする。

語彙には2種類ある。

**受容語彙**。読んで聞いてわかる語彙。

**産出語彙**。自分の口から出せる語彙。

この2つの差がえげつない。

Webbっていう研究者が測った。頻出上位1,000語レベルでは、使える率88%。まあまあ。

2,000語レベルで73%。

3,000語レベルで65%。

**覚える単語のレベルが上がるほど、口から出なくなる。**

日本人の英語学習者。受験英語で5,000語覚えた。TOEICのリーディングは読める。

でも会話で口から出るのは?

**たぶん1,500〜2,000。**

5,000語の物件を買ったのに、住めてる部屋は2,000。残り3,000部屋は鍵をなくした空室。

しかもLauferっていう研究者が追い打ちをかけた。勉強すればするほど、この空室率が上がる。

**知識が増えるほど、使えない知識の割合も増える。**

ゴミ屋敷と同じ原理。物は増える。使えるものの割合は減る。片付けないまま買い物だけ続けてる状態。

単語帳の5周目は、ゴミ屋敷に新しい棚を買い足してるのと同じ。

---

## 日本語は同じことを3回言わないと気が済まない言語

英語は important 1語。

日本語は大切、大事、インポータント。3語。

漢語と和語と外来語が混在してるから、同じ意味に3つの玄関がある。豪邸。

| 語彙数 | 英語カバー率 | 日本語カバー率 |
|--------|------------|-------------|
| 1,000 | 80.5% | 60.5% |
| 2,000 | 86.6% | 70.0% |
| 5,000 | 93.5% | 81.7% |

英語は1,000語で80%。日本語が80%に届くのは5,000語。5倍。

日本語は語彙に贅沢な言語。同じことを何通りも言える。美しい。

**でも学習者にとっては地獄。ミシュラン三つ星で普通のカレーが食べたいだけなのに、メニューが30ページある感じ。**

---

## よくある疑問

**じゃあ何語覚えればいいの?**

まず2,000語。これで日常テキストの87%をカバーできる。コスパ最高ゾーン。

2,000語以降は効率が壊滅する。5,000語追加して6.5%。もう一回言う。5,000語追加して6.5%。

**単語帳を何周もするのは無意味?**

1周目は意味がある。2周目もまあある。5周目は空室に家具を並べてるだけ。鍵がないのに。

問題は周回じゃなくて、バラバラの単語を覚えようとしてること。物語の中で出会った単語は忘れにくい。映画で覚えた英語、なぜか10年経っても出てくるでしょ。

**結局、何が一番効率いいの?**

上位2,000語を物語の中で聴く。キャラの声で覚える。塊で入れる。

単語帳は辞書を暗記してるのと同じ。辞書を暗記して喋れるようになった人、見たことない。

---

## だから俺のアプリは単語帳じゃない

単語を1個ずつ教えない。物語に埋め込んで、キャラの声で聴かせて、塊で覚えさせる。

ボーナスステージを最大限に活かして、地獄ステージを迂回する設計。

まだ迂回しきれてない。けどルートは見えてきた。

`,
