なぜ毎日書くのか。

現場で壁紙を貼ってると、1日が消える。朝入って夜出る。体は疲れてる。頭は使ってない。

書かないと、自分が今日何を考えたか忘れる。

書くと、昨日の自分と今日の自分の差分が見える。

