        memberContent: `## .envだけじゃ足りない理由

.envファイルにキーを入れる。これは最低限。

でもこれだけだと、APIエンドポイント自体は丸裸。

/api/chatにPOSTリクエストを投げれば、APIキーなしで俺のGPTが使える。サーバー側でキーを使ってるから、呼び出し側はキー不要。

つまりAPIキーの管理じゃなくて、エンドポイントの管理が本質。

対策は3つ:

1. 使ってないエンドポイントは消す（今日やった）
2. 認証を入れる（ログインしてないと叩けない）
3. レート制限を入れる（1分に10回まで、みたいな）

2と3は、Cloudflareを使ってるなら無料でできる。

Cloudflare Workers + Rate Limiting。
1日100万リクエストまで無料。そこにレート制限をかけるだけ。

俺はまだ2と3をやってない。
でも使ってないやつは全部消したから、リスクは大幅に減った。

---

## 作ったものを消す勇気

これが一番むずかしい。

8本のAPIを作った時、それぞれに3時間くらいかけてる。
合計24時間。

それを10秒で消した。

rm -rf src/app/api/chat
rm -rf src/app/api/quick-lookup
rm -rf src/app/api/extract-phrases

...

心理的に抵抗がある。
もったいない、と思う。
いつか使うかも、と思う。

でもいつか使うかも、は使わない。

コードは資産じゃない。
使ってないコードは負債だ。

存在するだけでメンテナンスコストが発生する。
セキュリティリスクが増える。
ビルド時間が伸びる。

消すのは勇気じゃない。
消さないのが怠慢だ。

---

## とにおのバイブコーディング塾 #07 -- 作ったものを消す勇気

前回はAPIがない外部サービスを自分のアプリの一部にする方法をやった。

今回のコツ: 使ってないコードは消せ。いつか使うかも、は使わない。

AIと作ると、作るのが速い。
速いから、たくさん作る。
たくさん作ると、使ってないものが溜まる。

バイブコーディングの落とし穴はここ。

作るのが簡単だから、消すのを忘れる。

AIに言えば5分でAPIが生える。便利。
でも5分で生えたものが8本溜まったら、それはもうゴミ屋敷だ。

今日やったこと:

x 全部残しておく。いつか使うかも
o 使ってないものは全部消す。残すものには理由がある

次回: #08（未定）`
