紅白で泣きながら歌った深愛。あの声は、5歳から毎日10曲歌い続けた声帯から出てきた。

英語は、明日急にうまくならない。

でも10年の反復は、声を変える。人生を変える。

それを教えてくれるのが水樹奈々。

だから好きだ。

