逆にした。

マスターしたカードはゴールドの背景に変えて、CLEARバッジをつけた。

**「やったね」って言ってくれる方向に設計を寄せた。**

これ、英会話マスター365の設計思想そのままで、「義務感で縛る」じゃなくて「また開きたい」で縛るやつ。褒めないと人間は続かない。

