各フレーズにコンテキスト解説がある。

日本語と英語の間にある溝を埋める、一番価値のある部分。

これを最初、クリックしないと読めないようにしてた。

なぜ。

**画面がスッキリするから。**

バカか。

一番大事なところを隠してどうする。スッキリさせたいなら、どうでもいい飾りを消せ。

