これはカミュの不条理そのもの。

岩を転がす理由はない。でも転がす。転がしている瞬間だけ、生きてる実感がある。

英語を勉強している瞬間だけ、死のことを忘れる。

いや、忘れてない。死と一緒に英語をやってる。

