もし、noteの全ての記事がAIで書かれる時代が来ても。

俺は読む。

なんでか。

**AIが書いたとしても、そのテーマを選んだのは、その人の人生だから。**

なんでこのテーマにしたんだろう。
なんでこの切り口を選んだんだろう。
なんで今日、これを書こうと思ったんだろう。

全部、人生からしか出てこない。

AIはツールだ。
ペンと同じだ。
ペンで書いた文章に魂がないとは誰も言わない。
同じことだ。

