比喩じゃない。

認知科学者のMoser-Mercer（1998年）が証明した。

同時通訳を30分続けると、ストレスホルモン（コルチゾール）が急上昇して、そのあと一気にクラッシュする。

脳が過負荷で強制シャットダウンする。

