この記事を読んで何を達成したい？にすぐ答えが出た人。

お前がターゲットだ。

---

この記事を読んで何を達成したい？にフリーズした人。

それも正直でいい。ただ、一度考えてみてくれ。
誰にも言われてないのに、自分でやりたいことって何だ。

小さくていい。
洋画を字幕なしで見たいでいい。
noteで英語について書いてみたいでいい。

その一行が書けたら、もうお前は5%の側にいる。

---

AIと深夜にこの話をしてた。

AIが聞いてきた。どっちを取る？親切に目標を提案するか、問いをそのまま突きつけるか。

答えは決まってる。

問いをそのまま突きつける。

去る者追わず、来る者拒まず。
