英語コーチの個人レッスン相場。月3万〜5万円。

月収30万に必要な生徒数。最低でも常時10〜15人。

平均的なサラリーマンの年収478万円（2024年、国税庁）に並ぶには、月約40万必要（社会保険の自己負担分を含めると）。つまり常時13〜15人の有料生徒が必要。

