        subtitle: 'phrase.meってサイトがある。洋画のセリフを音声つきで切り出してくれる凶器。これを耳と口に何百回も通す。さらに俺は、それを自分のアプリのカードに入れて毎日回せる。たぶんこれ、日本に5人しかやってない',
