字幕を信じてた頃の俺、何聞いても全然分かんなかった。

字幕を疑い始めてから、英語の「本物の音」が少しずつ見えてきた。

phrase.me + AI + 自分のアプリ。

この3点セットが揃ったの、たぶん2025年の今が初めてだ。

英語学習、ようやく面白くなってきた。

