        title: 'メリーポピンズ、 改めて観たら ツッコミどころで渋滞してた件',
        subtitle: '1964 年の名作、 大人になって観たら ちょっと違って見える。 履歴書なしで風に乗って来る、 業務はしない、 急に帰る -- それでも家族は救われる。 完全に意味不明、 でも泣ける。',
        tags: ['メリーポピンズ', '映画', 'ジョーク', '自虐', 'ディズニー', 'レビュー'],
        published: true,
        content: `## 久しぶりに観た

久しぶりにメリーポピンズ観た。
1964 年の名作、 大人になって観るとちょっと違って見える。

具体的に言うと、 ツッコミどころで渋滞してる。

## ツッコミ 1: 雇い方が無茶

メリーポピンズ、 履歴書なし、 面接なし、 推薦状なし、 ベビーシッター紹介所なし。

風に乗って空から降ってくる。
そして玄関で 私が新しいベビーシッターです と名乗る。

普通の家庭なら通報案件。
バンクス家、 普通に雇う。

## ツッコミ 2: 自己評価が事故

自己紹介で本人が言う。

あらゆる面で、 ほぼ完璧。

普通の社会人がこれ言ったら、 同僚から距離取られる。
メリーポピンズ、 サラッと言う。 しかも本当に完璧。
最強。

## ツッコミ 3: 業務をしていない

メリーポピンズの主な業務:

- 歌う
- 踊る
- 子供を煙突に連れて行く
- ペンギンと飯食う
- 親に説教する

家事は、 ほぼしてない (鞄から物出すシーンはある)。

ベビーシッターの職務記述書から、 大幅に逸脱してる。

## ツッコミ 4: 急に帰る

家族が良くなった瞬間、 風向きが変わって、 メリーポピンズは去る。

引き継ぎなし。
お別れ会なし。
退職届なし。
LINE のスタンプも残さない。

風の都合で出退勤するベビーシッター、 労基に持ち込んだら勝てる気がする。

## ツッコミ 5: なのに家族は本当に良くなる

ここが映画の最大の謎。

ベビーシッターが歌とダンスとペンギンで家族を救う。
普通なら破綻するはずの設定。

でも、 観終わると本当に ああ、 良かったな って思える。
1964 年のディズニー、 マジで天才。

## 結論

メリーポピンズ、 実在したら全力で雇いたい。

履歴書なし? 構わない。
風で来る? OK。
急に帰る? それでも来てほしい。

ベビーシッターの理想形が、 ぶっ飛び方向に振り切ってる。

たぶん今の俺の家の窓の外でも、 メリーポピンズが風向きを待ってる。
俺は窓を開けて待っとく。`,
