        title: 'ハチに刺された。 「walk it off」 と言った。 12秒後、 号泣していた',
        subtitle: '強がりの賞味期限は12秒。 そのあと俺は、 泣いてる自分を構造分析し始めた。 英語を構造分析して商品にした男の、 ただの職業病の話。',
        tags: ['英語表現', '自虐', 'ギャグ', '純ジャパ', 'ハチ', '構造分析'],
        published: true,
        content: `## 事件は、 ひとり英会話の途中で起きた

歩きながら、 ひとりで英語を喋っている。 毎日やってる。 はたから見れば、 完全に不審者だ。

その日も公園のへりを歩きながら、 "What did you do today?" と自分に質問していた。

左の二の腕に、 電流が走った。

ハチだった。

## 強がる ―― got stung, walk it off

刺された瞬間、 俺は声に出して言った。

「Walk it off.」

> got stung = 刺された。 sting の過去分詞。 ハチも、 クラゲも、 皮肉も、 ぜんぶ sting で刺してくる
> walk it off = 歩いて治せ。 痛い? 気にすんな、 動いてりゃ治る ―― という体育会系の呪文

英語の練習中だったから、 とっさのリアクションまで英語で出た。 ここだけ切り取れば、 そこそこ様になっている。

歩いてりゃ治る。 本気でそう思った。

## 崩壊する ―― bawling

治らなかった。

12秒後。 二の腕は俺の意思と無関係にふくらみ、 痛みのレベルが電流から火事に上がった。

俺は、 公園のへりで、 泣いていた。

> bawling = 号泣。 cry の上位互換。 声を出して、 顔をぐしゃぐしゃにして泣くやつ。 赤ん坊と、 ハチに刺された42歳が使う

walk it off から bawling まで、 12秒。 強がりの賞味期限は、 たった12秒だった。

ひとり英会話の不審者が、 ひとり号泣の不審者にジョブチェンジした。

## 分析する ―― the structural analysis

ここからが、 本当に書きたいことだ。

涙を流しながら、 俺の脳は勝手に動き出した。

「この涙は ―― 痛覚3割、 驚き4割、 いい歳して泣いてる羞恥3割の構造だな」

泣きながら、 自分の号泣を分解していた。

俺の商品は、 ネイティブの英語を構造分析して作った。 23秒の音声を解剖して、 学習システムにした。 それは仕事だ。

でも、 自分の涙まで解剖し始めたら、 もう仕事じゃない。 病気だ。

## 結論

ハチに刺された。 強がった。 12秒で号泣した。 そして泣きながら、 その号泣を構造分析した。

> make of that what you will = どう受け取るかはお任せします。 結論を相手に丸投げする、 知的なようで、 そのじつ無責任な決め台詞

構造分析の男は、 ハチに刺されても構造分析をやめられない。

Make of that what you will.

(刺された場所は、 まだ痛い。)`,
