これで楽になった。間違えても、止まらずに言い切る方が伝わる。直してもらうのは、あとでいい。

俺はレッスンを録音して、あとで書き起こして、間違いをまとめて直している。レッスン中は話すことだけに集中する。この仕組みを先生に説明したら、別の先生はそれを真似して、自分のタイ語の勉強に使い始めた。

